/* ===== Domain 3: Compute ===== */
GROUPS.push(
 {id:"c1",domain:"compute",name:"Automate deployment with ARM templates or Bicep",lessons:["arm","bicep"]},
 {id:"c2",domain:"compute",name:"Create and configure virtual machines",lessons:["vmcreate","disks","encrypt","avail","vmss","vmmove"]},
 {id:"c3",domain:"compute",name:"Provision and manage containers",lessons:["acr","aci"]},
 {id:"c4",domain:"compute",name:"Create and configure Azure App Service",lessons:["plan","slots","appnet"]}
);
DOMAINS.find(d=>d.id==="compute").built=true;

LESSONS.arm={id:"arm",title:"ARM templates",mins:3,
 keywords:["arm","arm template","json template","resource manager","parameters","variables","outputs","dependson","template functions","export template","parameter file","az deployment"],
 scenes:[
  {say:"An ARM template is a JSON file that declares the Azure resources you want. Resource Manager reads it and makes Azure match it.",
   ops:[B("tp","app",50,220,"main.json","ARM template"),B("arm","app",330,220,"Resource Manager","",200),B("rg","rg",620,70,"rg-web","Resource group",300,400),
        B("vm","cube",665,140,"vm-web1"),B("st","storage",665,250,"stweb01"),B("ip","ip",665,360,"pip-web1"),P(["tp","arm","vm"],"","ok"),P(["arm","st"],"","ok")]},
  {say:"A template has a few sections, and only resources is required.",
   ops:[C(),T("sec",60,60,[["Section","Purpose"],["$schema, contentVersion","Template format and your version"],["parameters","Values supplied at deploy time"],["variables","Reusable values computed inside"],["resources","What to deploy (required)"],["outputs","Values returned after deployment"]],"Template sections")]},
  {say:"Expressions in square brackets call template functions. Here the name comes from a parameter and the location from the resource group.",
   ops:[R("sec",1,"accent"),T("ex",60,290,[["Expressions"],["\"name\": \"[parameters('vmName')]\""],["\"location\": \"[resourceGroup().location]\""],["\"sku\": \"[variables('skuName')]\""]])]},
  {say:"dependsOn controls the order. A VM depends on its network interface, which depends on the virtual network.",
   ops:[C(),B("vn","route",60,200,"vnet-web","deployed 1st"),B("nic","app",350,200,"nic-web1","2nd · dependsOn vnet",230),B("vm","vm",690,200,"vm-web1","3rd · dependsOn nic",220),
        L("d1","nic","vn","dependsOn","dash"),L("d2","vm","nic","dependsOn","dash")]},
  {say:"Put values in a parameter file, so one template can deploy both dev and prod.",
   ops:[B("pd","app",200,360,"dev.parameters.json","vmSize: B2s",230),B("pp","app",520,360,"prod.parameters.json","vmSize: D4s_v5",230)]},
  {say:"Deploy with the Azure CLI or PowerShell, at resource group, subscription, management group or tenant scope.",
   ops:[C(),T("cmd",60,60,[["Scope","Azure CLI","PowerShell"],["Resource group","az deployment group create","New-AzResourceGroupDeployment"],["Subscription","az deployment sub create","New-AzSubscriptionDeployment"],["Management group","az deployment mg create","New-AzManagementGroupDeployment"],["Tenant","az deployment tenant create","New-AzTenantDeployment"]],"Deployment commands")]},
  {say:"Don't have a template? Export one from a resource group, a resource, or deployment history. Clean it up, then reuse it.",
   ops:[N("n1",60,300,"Export template: resource group · resource · deployment history\nthen parameterize names, locations and sizes","ok")]}
 ],
 takeaways:["Template sections: $schema, contentVersion, parameters, variables, resources (required), outputs.","Expressions use functions in brackets: parameters(), variables(), resourceGroup().location, resourceId().","dependsOn sets deployment order.","Parameter files let one template serve many environments.","az deployment group|sub|mg|tenant create, or the matching New-Az…Deployment cmdlets."],
 traps:["To deploy a resource group itself, deploy at subscription scope (az deployment sub create).","Hard-coded locations and names make templates fail elsewhere. Use parameters and resourceGroup().location."],
 mnemonic:"P-V-R-O: Parameters in, Variables inside, Resources built, Outputs out.",
 lab:"Export the template of a resource group with a storage account, change the account name to a parameter, and redeploy it to a new resource group with az deployment group create.",
 ref:"https://learn.microsoft.com/en-us/azure/azure-resource-manager/templates/overview"};

LESSONS.bicep={id:"bicep",title:"Bicep & deployment modes",mins:2,
 keywords:["bicep","decompile","bicep build","deployment mode","incremental","complete mode","what-if","template spec","module"],
 scenes:[
  {say:"Bicep is a simpler language for the same job. It compiles to an ARM template, so anything ARM can deploy, Bicep can too.",
   ops:[B("bc","app",60,200,"main.bicep","Bicep"),B("js","app",390,200,"main.json","ARM template"),B("arm","app",720,200,"Resource Manager","",200),L("l1","bc","js","az bicep build","dash"),L("l2","js","arm","deploy","ok"),P(["bc","js","arm"],"","ok")]},
  {say:"Going the other way, az bicep decompile turns an existing ARM template into Bicep.",
   ops:[P(["js","bc"],"decompile","signal")]},
  {say:"Here's how the two compare.",
   ops:[C(),T("cmp",60,60,[["","ARM JSON","Bicep"],["Syntax","Verbose JSON","Concise, readable"],["Parameter","\"parameters\": { … }","param vmName string"],["Reference","[parameters('vmName')]","vmName"],["Dependencies","dependsOn, written by hand","Mostly automatic"],["Reuse","Linked templates","module keyword"]],"ARM vs Bicep")]},
  {say:"Deployment mode matters. Incremental, the default, adds and updates resources in the template and leaves everything else alone.",
   ops:[C(),B("rg","rg",40,60,"rg-app","Resource group",400,420),B("a","cube",80,140,"vm-a","in template"),B("b","storage",80,240,"st-b","in template"),B("o","cube",80,340,"vm-old","not in template"),
        B("tp","app",620,140,"main.bicep","vm-a, st-b"),P(["tp","a"],"","ok"),P(["tp","b"],"","ok"),N("n1",500,260,"Incremental (default): vm-old is kept","ok")]},
  {say:"Complete mode deletes every resource in the resource group that isn't in the template. Here, vm-old would be deleted.",
   ops:[...D("n1"),M("o","bad"),SET("o","vm-old","deleted"),N("n2",500,260,"Complete: not in template → deleted","bad")]},
  {say:"Before deploying, run what-if to preview what will be created, changed and deleted.",
   ops:[N("n3",500,340,"az deployment group what-if …\n+ create   ~ modify   − delete","accent")]}
 ],
 takeaways:["Bicep compiles to ARM JSON (az bicep build); az bicep decompile converts ARM to Bicep.","Bicep handles most dependencies automatically and uses modules for reuse.","Incremental (default) leaves unlisted resources; Complete deletes them.","Complete mode applies only to resource group deployments.","what-if previews changes before you deploy."],
 traps:["Deploying a template with only one resource in Complete mode deletes everything else in that resource group.","Bicep files are deployed with the same az deployment / New-Az…Deployment commands as ARM templates."],
 mnemonic:"Incremental adds. Complete cleans house.",
 lab:"Write a Bicep file that creates one storage account. Deploy it with --what-if, then deploy for real, then decompile an exported ARM template to Bicep.",
 ref:"https://learn.microsoft.com/en-us/azure/azure-resource-manager/bicep/overview"};

LESSONS.vmcreate={id:"vmcreate",title:"Creating & resizing VMs",mins:2,
 keywords:["virtual machine","vm","vm size","resize","deallocate","stopped","b series","d series","e series","spot vm","auto-shutdown"],
 scenes:[
  {say:"Creating a VM means choosing a region, image, size, disks, network and an admin login.",
   ops:[T("cr",60,60,[["Tab","Key choices"],["Basics","Region, availability, image, size, admin account"],["Disks","OS disk type, data disks, encryption"],["Networking","VNet, subnet, public IP, NSG"],["Management","Auto-shutdown, backup, identity"],["Monitoring","Boot diagnostics, insights"]],"Create a virtual machine")]},
  {say:"Sizes come in families. Pick the family that matches the workload.",
   ops:[C(),T("fam",60,60,[["Series","Best for"],["B","Burstable, low-cost dev/test"],["D","General purpose"],["E","Memory-optimized (databases)"],["F","Compute-optimized"],["L","Storage-optimized"],["N","GPU workloads"]],"VM size families")]},
  {say:"You can resize a VM later. If the new size is available on the current hardware cluster, you resize while it runs, and it restarts.",
   ops:[B("vm","vm",440,80,"vm-app1","D2s_v5 → D4s_v5",240),N("n1",440,170,"Resize = restart. Plan for downtime.","accent")]},
  {say:"If the size you want isn't listed, deallocate the VM first. Then every size in the region becomes available.",
   ops:[SET("vm","vm-app1","Stopped (deallocated)"),N("n2",440,240,"Size not listed? Stop (deallocate) → resize","accent")]},
  {say:"Shutting down inside the guest OS isn't deallocating. You keep paying for compute until you stop the VM from Azure.",
   ops:[T("st",440,310,[["VM state","Compute billed?"],["Running","Yes"],["Stopped (from inside the OS)","Yes"],["Stopped (deallocated)","No"]])]},
  {say:"Auto-shutdown and Spot VMs cut costs for dev and test. Reserved instances and savings plans cut them for steady workloads.",
   ops:[N("n3",60,330,"Save: auto-shutdown · Spot VMs\nReservations / savings plans","ok")]}
 ],
 takeaways:["Families: B burstable, D general, E memory, F compute, L storage, N GPU.","Resizing restarts the VM. If the size isn't offered, deallocate first.","Stopped from the OS still bills compute; Stopped (deallocated) doesn't.","Spot VMs are cheap but can be evicted at any time."],
 traps:["\"Stop the VM to save cost\" means deallocate from Azure, not shut down the OS.","Deallocating releases a dynamic public IP and wipes the temporary disk."],
 mnemonic:"B for Budget, D for Default, E for Extra memory, F for Fast CPU, N for Nvidia.",
 lab:"Create a B-series VM with auto-shutdown at 7 PM. Resize it to a D-series size while running, then stop it from the portal and check the status says deallocated.",
 ref:"https://learn.microsoft.com/en-us/azure/virtual-machines/sizes/overview"};

LESSONS.disks={id:"disks",title:"Managed disks",mins:3,
 keywords:["managed disk","os disk","data disk","temporary disk","premium ssd","standard ssd","standard hdd","ultra disk","premium ssd v2","snapshot","disk resize","attach disk"],
 scenes:[
  {say:"Every VM has an OS disk and usually a temporary disk. You add data disks for applications and databases.",
   ops:[B("vm","vm",380,40,"vm-db1","",200),B("os","storage",60,220,"OS disk","C: · persistent",200),B("tmp","storage",380,220,"Temporary disk","D: · not persistent",200),B("dd","storage",700,220,"Data disk","F: · persistent",200),
        L("l1","vm","os"),L("l2","vm","tmp"),L("l3","vm","dd")]},
  {say:"The temporary disk is wiped when the VM is deallocated or moved to a new host. Never keep data you need there.",
   ops:[M("tmp","bad"),N("n1",280,330,"Temporary disk: wiped on deallocate or redeploy","bad")]},
  {say:"Managed disk types, from cheapest to fastest.",
   ops:[C(),T("dt",60,60,[["Type","Typical use","OS disk?"],["Standard HDD","Backups, infrequent access","Yes"],["Standard SSD","Web servers, light dev/test","Yes"],["Premium SSD","Production, databases","Yes"],["Premium SSD v2","High IOPS, tunable performance","No"],["Ultra Disk","Highest IOPS, SAP HANA, top-tier DBs","No"]],"Managed disk types")]},
  {say:"You can increase a disk's size but never shrink it. Changing a disk's type, like Standard to Premium, needs the VM deallocated.",
   ops:[N("n2",60,300,"Size: increase only, never shrink\nChange type: deallocate the VM first","accent")]},
  {say:"Snapshots are point-in-time copies of a disk, full or incremental. Create a new disk from a snapshot to restore or clone.",
   ops:[B("d1","storage",560,300,"disk-data",""),B("sn","storage",760,300,"snap-0601","incremental",170),L("ls","d1","sn","snapshot","dash")]},
  {say:"Data disks can be attached or detached while the VM runs. How many you can attach depends on the VM size.",
   ops:[N("n3",60,400,"Attach / detach data disks while running ✓\nMax number of data disks = set by VM size","ok")]}
 ],
 takeaways:["OS disk and data disks are persistent managed disks; the temporary disk is not.","Types: Standard HDD < Standard SSD < Premium SSD < Premium SSD v2 < Ultra.","Premium SSD v2 and Ultra Disk can't be OS disks.","Disks can grow, never shrink. Changing type needs the VM deallocated.","Snapshots (full or incremental) can create new disks."],
 traps:["Data on the temporary (D:) disk is lost after deallocation, resize to another host, or redeploy.","Premium SSD needs a VM size that supports premium storage (sizes with an 's', like D4s_v5)."],
 mnemonic:"Temp disk = whiteboard: wiped when you leave the room.",
 lab:"Attach a new 32 GiB Standard SSD data disk to a running VM, initialize it in the OS, then take an incremental snapshot and create a disk from it.",
 ref:"https://learn.microsoft.com/en-us/azure/virtual-machines/managed-disks-overview"};

LESSONS.encrypt={id:"encrypt",title:"VM disk encryption",mins:2,
 keywords:["encryption","server-side encryption","sse","encryption at host","azure disk encryption","ade","bitlocker","dm-crypt","disk encryption set","customer-managed key","key vault"],
 scenes:[
  {say:"Every managed disk is encrypted at rest by default, using server-side encryption with platform-managed keys. Nothing to configure.",
   ops:[B("vm","vm",60,200,"vm-app1"),B("dk","storage",380,200,"disk-os","SSE · platform key",190),L("l1","vm","dk"),N("n1",60,330,"Default: SSE with platform-managed keys","ok")]},
  {say:"Want to control the keys? Use customer-managed keys in Key Vault, linked to disks through a disk encryption set.",
   ops:[B("kv","key",700,60,"Key Vault","your key",200),B("des","lock",700,200,"Disk encryption set","",220),L("l2","kv","des","key","dash"),L("l3","des","dk","customer-managed key","ok"),SET("dk","disk-os","SSE · customer key")]},
  {say:"Encryption at host goes further. Temp disks and caches are encrypted on the host itself. Register the feature on the subscription first.",
   ops:[...D("n1"),N("n2",60,330,"Encryption at host: also temp disk + caches\nRegister: Microsoft.Compute/EncryptionAtHost","accent")]},
  {say:"Azure Disk Encryption encrypts inside the guest with BitLocker or DM-Crypt, keys in Key Vault. Microsoft now recommends encryption at host, as ADE retires in 2028.",
   ops:[...D("n2"),N("n3",60,330,"ADE: BitLocker (Windows) / DM-Crypt (Linux)\nRetiring Sept 2028 → prefer encryption at host","bad")]},
  {say:"For Azure Disk Encryption, the Key Vault must be in the same region and subscription as the VM, with disk encryption access turned on.",
   ops:[...D("n3"),N("n4",60,330,"ADE Key Vault: same region + subscription\nAccess: Azure Disk Encryption for volume encryption","accent")]},
  {say:"Here are the options side by side.",
   ops:[C(),T("cmp",60,80,[["Option","Where it encrypts","Keys"],["Server-side encryption","Storage service (default)","Platform or customer-managed"],["Encryption at host","VM host: disks, temp disk, caches","Platform or customer-managed"],["Azure Disk Encryption","Inside the guest OS","Key Vault (BitLocker/DM-Crypt)"]],"Disk encryption options")]}
 ],
 takeaways:["All managed disks get SSE with platform-managed keys by default.","Customer-managed keys use Key Vault + a disk encryption set.","Encryption at host also covers temp disks and caches; register the subscription feature first.","ADE encrypts in the guest; Key Vault must match region and subscription. Microsoft recommends encryption at host for new VMs."],
 traps:["\"Encrypt the temporary disk\" → encryption at host (or ADE), not SSE alone.","ADE fails if the Key Vault is in another region or doesn't allow disk encryption access."],
 mnemonic:"SSE at rest, Host for the rest, ADE inside the guest.",
 lab:"Register EncryptionAtHost on a test subscription, create a VM with encryption at host enabled, and check the setting on the VM's Disks blade.",
 ref:"https://learn.microsoft.com/en-us/azure/virtual-machines/disk-encryption-overview"};

LESSONS.avail={id:"avail",title:"Availability sets & zones",mins:3,
 keywords:["availability set","availability zone","fault domain","update domain","sla","99.95","99.99","high availability","zone redundant"],
 scenes:[
  {say:"Hardware fails, and Azure patches hosts. Availability options keep your app running through both.",
   ops:[B("as","vnet",30,50,"avset-web","Availability set",570,440),B("f0","group",50,100,"FD 0","",170,370),B("f1","group",230,100,"FD 1","",170,370),B("f2","group",410,100,"FD 2","",170,370),
        B("v0","vm",60,160,"vm-1","UD 0"),B("v1","vm",240,160,"vm-2","UD 1"),B("v2","vm",420,160,"vm-3","UD 2")]},
  {say:"An availability set spreads VMs across fault domains: separate racks with their own power and network. Up to three.",
   ops:[H("f0"),H("f1"),H("f2"),N("n1",620,80,"Fault domain = rack\n(own power + network)\nUp to 3","accent")]},
  {say:"It also spreads them across update domains, which reboot one at a time during maintenance. Up to twenty, five by default.",
   ops:[N("n2",620,200,"Update domain = reboot group\nUp to 20 (default 5)","accent")]},
  {say:"Two or more VMs in an availability set get a 99.95 percent SLA. You must choose the set when you create the VM.",
   ops:[N("n3",620,300,"SLA 99.95% (2+ VMs)\nChosen at VM creation only","ok")]},
  {say:"Availability zones go further: separate datacenters within a region. Spread VMs across zones for a 99.99 percent SLA.",
   ops:[C(),B("rg","mg",30,40,"Central India","Region with availability zones",900,460),B("z1","group",60,100,"Zone 1","",270,290),B("z2","group",345,100,"Zone 2","",270,290),B("z3","group",630,100,"Zone 3","",270,290),
        B("a","vm",120,180,"vm-1"),B("b","vm",405,180,"vm-2"),B("c","vm",690,180,"vm-3"),N("n4",60,410,"Zones: separate datacenters · 2+ VMs across zones = 99.99%","ok")]},
  {say:"Here are the SLA numbers to memorize.",
   ops:[C(),T("sla",180,120,[["Deployment","VM SLA"],["Single VM with Premium SSD or Ultra disks","99.9%"],["Availability set (2+ VMs)","99.95%"],["Across availability zones (2+ VMs)","99.99%"]],"Virtual machine SLAs")]},
  {say:"A VM uses either an availability set or an availability zone, not both. Prefer zones where the region supports them.",
   ops:[N("n5",180,330,"Availability set OR zone, never both","bad")]}
 ],
 takeaways:["Availability set: up to 3 fault domains and 20 update domains (default 5); 99.95% SLA with 2+ VMs.","Availability zones: separate datacenters; 99.99% SLA with 2+ VMs across zones.","Single VM with Premium SSD/Ultra: 99.9%.","A VM joins an availability set only at creation."],
 traps:["You can't add an existing VM to an availability set. Recreate it from its disks.","\"Survive a datacenter failure\" → availability zones, not availability sets."],
 mnemonic:"Rack (fault), Reboot (update), Region building (zone): 3, 20, 3.",
 lab:"Create an availability set with 2 fault domains and 5 update domains, add two VMs at creation, then check which FD/UD each VM landed in.",
 ref:"https://learn.microsoft.com/en-us/azure/virtual-machines/availability"};

LESSONS.vmss={id:"vmss",title:"Virtual machine scale sets",mins:3,
 keywords:["vmss","scale set","virtual machine scale set","autoscale","scale out","scale in","scale-in policy","orchestration mode","flexible","uniform","upgrade policy","cooldown"],
 scenes:[
  {say:"A virtual machine scale set runs a group of VMs and adds or removes them automatically.",
   ops:[B("lb","lb",40,120,"lb-web","Load balancer",170),B("ss","vnet",420,60,"vmss-web","Scale set",500,420),B("i0","vm",460,120,"vmss_0"),B("i1","vm",680,120,"vmss_1"),P(["lb","i0"],"","signal"),P(["lb","i1"],"","signal")]},
  {say:"Autoscale rules watch a metric, like average CPU, and set minimum, maximum and default instance counts.",
   ops:[T("ru",20,250,[["Rule","Action"],["CPU > 70% for 10 min","Add 1 instance"],["CPU < 30% for 10 min","Remove 1 instance"],["Limits","Min 2 · Max 10 · Default 2"]],"Autoscale")]},
  {say:"When CPU stays high, autoscale adds instances. After a cooldown, five minutes by default, it evaluates again.",
   ops:[R("ru",1,"accent"),B("i2","vm",460,220,"vmss_2","new"),B("i3","vm",680,220,"vmss_3","new"),P(["lb","i2"],"","signal"),P(["lb","i3"],"","signal")]},
  {say:"When load drops, scale-in removes instances. The scale-in policy decides which: Default balances across zones, then removes the highest instance ID. Or choose newest or oldest.",
   ops:[R("ru",2,"accent"),M("i3","bad"),N("n1",20,420,"Scale-in policy: Default · NewestVM · OldestVM","accent")]},
  {say:"Orchestration mode: Flexible, now the default, supports mixed sizes and standard VM features. Uniform runs identical instances managed as one.",
   ops:[C(),T("om",60,60,[["","Flexible (default)","Uniform"],["Instances","Standard VMs, can mix sizes","Identical instances"],["Best for","Most new workloads","Large stateless, identical fleets"],["Manage","Like individual VMs","Through the scale set model"]],"Orchestration modes")]},
  {say:"Upgrade policy controls how model changes reach existing instances: manual, automatic, or rolling in batches.",
   ops:[T("up",60,260,[["Upgrade policy","Behavior"],["Manual","You choose when to update instances"],["Automatic","All instances updated, possibly at once"],["Rolling","Updated in batches with pauses"]])]},
  {say:"Exam wording: scale out means more instances. Scale up means a bigger VM size. Scale sets autoscale out and in.",
   ops:[N("n2",560,280,"Scale OUT/IN = number of instances\nScale UP/DOWN = size of each VM","ok")]}
 ],
 takeaways:["Autoscale: metric rules (e.g. CPU) + min/max/default instances + cooldown (5 min default).","Scale-in policy: Default, NewestVM, OldestVM.","Flexible orchestration is the default; Uniform for identical fleets.","Upgrade policy: Manual, Automatic, Rolling.","Scale out = more instances; scale up = bigger size."],
 traps:["Without a scale-in rule, a scale set grows and never shrinks.","Autoscale never goes below the minimum or above the maximum, whatever the metric says."],
 mnemonic:"Out is more, Up is bigger.",
 lab:"Create a scale set with 2 instances and a rule to add 1 when CPU > 70% for 5 minutes. Run a CPU stress tool on an instance and watch the instance count.",
 ref:"https://learn.microsoft.com/en-us/azure/virtual-machine-scale-sets/overview"};

LESSONS.vmmove={id:"vmmove",title:"Moving & redeploying VMs",mins:2,
 keywords:["move vm","move virtual machine","resource mover","site recovery","another region","redeploy","move to another subscription"],
 scenes:[
  {say:"Moving a VM to another resource group or subscription is a resource move. Its disks, network interface and public IP move with it.",
   ops:[B("rg1","rg",40,60,"rg-old","",400,420),B("rg2","rg",520,60,"rg-new","",400,420),B("gr","group",70,110,"Move together","",290,330),
        B("vm","vm",100,160,"vm-app1"),B("dk","storage",100,250,"disk-os"),B("nic","app",100,340,"nic-app1"),P(["gr","rg2"],"move","ok")]},
  {say:"Same region, new resource ID. Both resource groups are locked for writes during the move, and the VM keeps running.",
   ops:[N("n1",560,160,"Region unchanged · ID changes\nVM stays running during the move","accent")]},
  {say:"Moving to another region is different. Use Azure Resource Mover, or Azure Site Recovery, which replicate the VM and recreate it in the target region.",
   ops:[C(),B("r1","mg",40,80,"East US","source",380,300),B("r2","mg",540,80,"Central India","target",380,300),B("va","vm",120,180,"vm-app1"),B("vb","vm",620,180,"vm-app1","replica"),
        L("lm","va","vb","Resource Mover / Site Recovery","dash"),P(["va","vb"],"replicate","signal")]},
  {say:"Redeploy is a third option. It moves the VM to a new host in the same region, which often fixes stubborn connectivity issues. The temporary disk is lost.",
   ops:[N("n2",40,410,"Redeploy: new host, same region · temp disk data lost","bad")]},
  {say:"Here's the quick decision table.",
   ops:[C(),T("dec",100,100,[["Need","Use"],["New resource group or subscription","Move resources"],["New region","Azure Resource Mover or Site Recovery"],["Odd host or RDP issues","Redeploy"],["New availability set","Recreate the VM from its disks"]],"Moving VMs")]}
 ],
 takeaways:["Resource moves (RG or subscription) keep the region; move dependent resources together.","Cross-region: Azure Resource Mover or Azure Site Recovery.","Redeploy moves to a new host in the same region; temp disk data is lost.","Changing a VM's availability set means recreating it from its disks."],
 traps:["A resource move never changes the region.","Redeploying causes a reboot and loses the temporary disk."],
 mnemonic:"Different group → Move. Different region → Mover. Different host → Redeploy.",
 lab:"Move a small VM with its disk and NIC to a new resource group, then use Redeploy + reapply on it and note what happens to the D: drive.",
 ref:"https://learn.microsoft.com/en-us/azure/resource-mover/overview"};

LESSONS.acr={id:"acr",title:"Azure Container Registry",mins:2,
 keywords:["acr","container registry","azure container registry","docker push","acr build","acr tasks","acrpull","admin user","geo-replication","container image"],
 scenes:[
  {say:"Azure Container Registry is a private registry for container images, like your own Docker Hub inside Azure.",
   ops:[B("dev","user",40,220,"Developer","docker push"),B("acr","app",340,220,"crcontoso.azurecr.io","Container registry",260),B("ca","app",730,120,"Container Apps","",190),B("ci","cube",730,320,"Container Instances","",190),
        P(["dev","acr"],"push","signal"),P(["acr","ca"],"pull","ok"),P(["acr","ci"],"pull","ok")]},
  {say:"ACR Tasks builds images in the cloud. Run az acr build and you don't need Docker on your machine.",
   ops:[N("n1",280,330,"az acr build --registry crcontoso --image web:v1 .","accent")]},
  {say:"Three SKUs. Premium adds geo-replication, private endpoints and the most throughput.",
   ops:[...D("n1"),T("sku",280,330,[["SKU","Adds"],["Basic","Learning, low volume"],["Standard","More storage and throughput"],["Premium","Geo-replication, private endpoints, max throughput"]],"ACR SKUs")]},
  {say:"The admin user is disabled by default. Prefer Entra identities: give the app's managed identity the AcrPull role on the registry.",
   ops:[...D("sku"),N("n2",280,340,"Pull with managed identity + AcrPull role\nAdmin user: off by default, avoid in production","ok")]},
  {say:"Registry names are global, so crcontoso dot azurecr dot io must be unique across all of Azure.",
   ops:[...D("n2"),N("n3",280,340,"Registry name: globally unique, 5–50 alphanumerics","accent")]}
 ],
 takeaways:["ACR stores private container images and Helm charts.","az acr build builds images in Azure (ACR Tasks).","SKUs: Basic, Standard, Premium (geo-replication, private endpoints).","Use managed identities with AcrPull/AcrPush roles; admin user is off by default."],
 traps:["Geo-replication and private endpoints need Premium.","An app pulling images needs AcrPull, not Reader."],
 mnemonic:"Push to ACR, Pull with AcrPull.",
 lab:"Create a Basic registry and run az acr build on a sample Dockerfile, then run the image in Azure Container Instances using a managed identity.",
 ref:"https://learn.microsoft.com/en-us/azure/container-registry/container-registry-intro"};

LESSONS.aci={id:"aci",title:"Container Instances vs Container Apps",mins:3,
 keywords:["aci","container instances","container group","restart policy","container apps","keda","scale to zero","revisions","ingress","dapr","aks","containers"],
 scenes:[
  {say:"Azure Container Instances runs containers without managing any servers. It's the fastest way to run a single container.",
   ops:[B("img","app",40,220,"web:v1","image in ACR"),B("cg","vnet",280,80,"cg-web","Container group",340,330),B("c1","cube",320,150,"web","1 vCPU · 1.5 GB",190),B("c2","cube",320,250,"log-sidecar","0.5 vCPU · 0.5 GB",190),
        P(["img","c1"],"run","ok")]},
  {say:"A container group shares a lifecycle, network and storage, like a Kubernetes pod. Containers in it talk over localhost.",
   ops:[L("lc","c1","c2","localhost","dash"),N("n1",650,100,"Shared: IP, ports,\nvolumes, lifecycle","accent")]},
  {say:"You set CPU and memory for each container, and a restart policy. ACI doesn't autoscale.",
   ops:[...D("n1"),T("rp",650,80,[["Restart policy","Use"],["Always","Web servers (default)"],["OnFailure","Batch jobs"],["Never","Run once"]]),N("n2",280,430,"ACI: no autoscale","bad")]},
  {say:"Azure Container Apps runs on managed Kubernetes. It scales on HTTP traffic, CPU or queue length, and can scale down to zero.",
   ops:[C(),B("env","vnet",40,60,"Container Apps environment","",560,420),B("a1","cube",80,140,"api","rev 2 · 80%"),B("a2","cube",80,240,"api","rev 1 · 20%"),B("a3","cube",330,140,"worker","0 replicas"),
        N("n3",620,90,"Scale rules (KEDA):\nHTTP · CPU · queue length\nScale to zero ✓","ok")]},
  {say:"Container Apps adds revisions for safe rollouts and traffic splitting, built-in ingress, and Dapr for microservices.",
   ops:[N("n4",620,230,"Revisions + traffic split\nIngress · Dapr","accent")]},
  {say:"Which one? Pick by how much control and scaling you need.",
   ops:[C(),T("cmp",60,80,[["","Container Instances","Container Apps","AKS"],["Best for","Single containers, jobs","Microservices, APIs","Full Kubernetes control"],["Autoscale","No","Yes, to zero","Yes"],["You manage","Almost nothing","Almost nothing","Cluster and nodes"]],"Choosing a container service")]}
 ],
 takeaways:["ACI: serverless containers; container groups share network, storage and lifecycle.","Restart policies: Always (default), OnFailure, Never.","ACI sizes CPU/memory per container and doesn't autoscale.","Container Apps: KEDA-based scaling (HTTP, CPU, queues), scale to zero, revisions, ingress, Dapr."],
 traps:["\"Scale automatically based on queue length\" → Container Apps, not ACI.","A batch job that should stop after success → restart policy OnFailure or Never, not Always."],
 mnemonic:"ACI = one-off taxi. Container Apps = ride-share fleet that grows with demand.",
 lab:"Run mcr.microsoft.com/azuredocs/aci-helloworld in ACI with a public DNS name, then deploy the same image to Container Apps with an HTTP scale rule.",
 ref:"https://learn.microsoft.com/en-us/azure/container-instances/container-instances-overview"};

LESSONS.plan={id:"plan",title:"App Service plans",mins:2,
 keywords:["app service","app service plan","web app","tier","basic","standard","premium","isolated","scale up","scale out","autoscale"],
 scenes:[
  {say:"Web apps run on an App Service plan, the set of VMs that hosts them. All apps in a plan share its instances.",
   ops:[B("pl","vnet",40,60,"asp-prod","App Service plan · S1 · 2 instances",500,420),B("w1","app",80,150,"app-shop","web app",190),B("w2","app",310,150,"app-api","web app",190),
        B("i0","vm",80,300,"instance 1",""),B("i1","vm",310,300,"instance 2","")]},
  {say:"The tier decides features and limits.",
   ops:[T("ti",560,60,[["Tier","Key features"],["Free / Shared","Dev/test, shared hardware"],["Basic","Custom domains + TLS, up to 3 instances"],["Standard","Autoscale up to 10, 5 slots"],["Premium v3","Up to 30 instances, 20 slots"],["Isolated v2","Dedicated App Service Environment"]],"Pricing tiers")]},
  {say:"Scale up means a bigger tier or instance size. Scale out means more instances. Autoscale needs Standard or higher.",
   ops:[R("ti",3,"accent"),N("n1",560,300,"Scale up = bigger tier/size\nScale out = more instances","accent")]},
  {say:"A plan lives in one region. To move an app to another plan, the plan must be in the same resource group and region.",
   ops:[...D("n1"),N("n2",560,300,"Move app to another plan:\nsame resource group + same region","bad")]},
  {say:"Exam tip: the cheapest tier with custom domains and TLS is Basic. For deployment slots or autoscale, it's Standard.",
   ops:[...D("n2"),N("n3",560,300,"Custom domain + TLS → Basic\nSlots or autoscale → Standard","ok")]}
 ],
 takeaways:["Apps in a plan share its VMs; the plan sets region, tier and instance count.","Basic: custom domains, TLS, manual scale to 3. Standard: autoscale to 10, 5 slots. Premium v3: 30 instances, 20 slots.","Scale up = tier/size; scale out = instances.","Moving an app between plans requires the same resource group and region."],
 traps:["Free and Shared tiers can't bind TLS certificates to custom domains.","Two apps on one plan compete for the same CPU and memory."],
 mnemonic:"Basic gets a Badge (TLS), Standard gets Slots and Scale.",
 lab:"Create a B1 plan with a web app, scale it out to 2 instances, then scale up to S1 and add an autoscale rule on CPU.",
 ref:"https://learn.microsoft.com/en-us/azure/app-service/overview-hosting-plans"};

LESSONS.slots={id:"slots",title:"Deployment slots",mins:2,
 keywords:["deployment slot","slot","swap","staging","slot setting","sticky setting","swap with preview","auto swap","testing in production","traffic routing"],
 scenes:[
  {say:"Deployment slots are live copies of your app with their own hostnames, like a staging slot next to production.",
   ops:[B("u","users",40,220,"Users"),B("pr","app",360,120,"app-shop","production",220),B("st","app",360,320,"app-shop-staging","staging slot",220),P(["u","pr"],"","ok")]},
  {say:"Deploy to staging, warm it up, then swap. The swap has no downtime, and you can swap back if something breaks.",
   ops:[SET("st","app-shop-staging","v2 deployed"),L("sw","pr","st","swap","dash"),SET("pr","app-shop","production · v2"),SET("st","app-shop-staging","v1 (swap back ready)")]},
  {say:"Some settings swap with the code. Others stick to their slot. Mark an app setting as a deployment slot setting to keep it in place.",
   ops:[T("set",680,60,[["Swaps","Stays with slot"],["App code","Slot-setting app settings"],["App settings","Custom domains"],["Connection strings","TLS bindings"],["Handler mappings","Scale settings"],["","IP restrictions"]],"On swap")]},
  {say:"Want real users to test staging first? Route a percentage of traffic to it.",
   ops:[P(["u","st"],"10%","signal"),N("n1",40,400,"Testing in production: route 10% to staging","accent")]},
  {say:"Slots need Standard or higher: five in Standard, twenty in Premium. Swap with preview lets you validate before completing.",
   ops:[...D("n1"),N("n2",40,400,"Slots: Standard (5) · Premium (20)\nSwap with preview · auto swap","ok")]}
 ],
 takeaways:["Slots are live apps with their own hostnames; swap is zero-downtime and reversible.","Mark settings as deployment slot settings to keep them with the slot.","Custom domains, TLS bindings, scale settings and IP restrictions never swap.","Traffic routing sends a percentage of users to a slot.","Standard: 5 slots; Premium: 20."],
 traps:["A production database connection string that swaps into staging is a classic incident. Make it a slot setting.","Basic tier has no deployment slots."],
 mnemonic:"Code travels, slot settings stay home.",
 lab:"On an S1 app, add a staging slot, set an app setting ENV=staging as a slot setting, deploy a change, and swap. Check ENV in both slots afterwards.",
 ref:"https://learn.microsoft.com/en-us/azure/app-service/deploy-staging-slots"};

LESSONS.appnet={id:"appnet",title:"App Service domains, TLS & networking",mins:3,
 keywords:["custom domain","asuid","txt record","cname","tls","ssl","certificate","managed certificate","https only","vnet integration","private endpoint","access restrictions","app service networking"],
 scenes:[
  {say:"To use your own domain, add a CNAME for a subdomain like www, or an A record for the root. A TXT record named asuid proves you own it.",
   ops:[T("dn",60,60,[["Record","Name","Value"],["CNAME","www","app-shop.azurewebsites.net"],["A","@","Inbound IP of the app"],["TXT","asuid.www","Custom domain verification ID"]],"DNS at your provider")]},
  {say:"Then bind a TLS certificate. Use a free App Service managed certificate, import one from Key Vault, or upload a PFX file.",
   ops:[T("ce",60,240,[["Certificate","Notes"],["App Service managed","Free, auto-renews, no wildcard"],["Key Vault import","Central management, renewals"],["Upload PFX","Your own certificate file"]],"TLS certificates")]},
  {say:"Turn on HTTPS Only, and set a minimum TLS version.",
   ops:[N("n1",560,260,"HTTPS Only: On\nMinimum TLS version: 1.2","ok")]},
  {say:"For outbound traffic to private resources, use VNet integration. The app reaches a database in a subnet without exposing it.",
   ops:[C(),B("app","app",60,220,"app-shop","web app",190),B("vn","vnet",380,60,"vnet-data","",540,420),B("si","subnet",410,110,"snet-integration","delegated to Microsoft.Web",480,120),B("sd","subnet",410,270,"snet-db","",480,170),
        B("db","sql",560,330,"sql-orders","private"),L("li","app","si","VNet integration","dash"),P(["app","db"],"outbound","ok")]},
  {say:"For private inbound access, add a private endpoint. The app gets a private IP, so users reach it only from your network.",
   ops:[N("n2",40,330,"Inbound private:\nprivate endpoint","accent"),N("n3",40,410,"Outbound to VNet:\nVNet integration","accent")]},
  {say:"Access restrictions allow or deny inbound traffic by IP range, service tag or subnet, like a firewall for the app.",
   ops:[...D("n2","n3"),N("n4",40,330,"Access restrictions:\nIP · service tag · subnet","ok")]}
 ],
 takeaways:["Custom domain: CNAME (subdomain) or A record (apex) + TXT asuid record for verification.","TLS: free managed certificate (no wildcard), Key Vault import, or PFX upload. Needs Basic or higher.","HTTPS Only + minimum TLS version harden the app.","VNet integration = outbound into a VNet (delegated subnet). Private endpoint = private inbound.","Access restrictions filter inbound by IP, service tag or subnet."],
 traps:["VNet integration doesn't make the app private. That's a private endpoint.","Managed certificates don't support wildcard domains."],
 mnemonic:"Integration goes OUT, endpoint lets IN.",
 lab:"Add a custom subdomain to a B1 web app using a CNAME and asuid TXT record, bind a free managed certificate, and turn on HTTPS Only.",
 ref:"https://learn.microsoft.com/en-us/azure/app-service/app-service-web-tutorial-custom-domain"};

